// Call invokes a namespace.method by name, filling path/query/body from params.
func (c *Client) Call(ctx context.Context, namespace, method string, params map[string]any) (json.RawMessage, error) {
	r, ok := routes[namespace][method]
	if !ok {
		return nil, &APIError{Status: 0, Message: "unknown method " + namespace + "." + method}
	}
	path := r.Path
	query := map[string]string{}
	var body any
	for _, p := range r.Params {
		v, present := params[p.Name]
		if !present {
			continue
		}
		switch p.In {
		case "body":
			body = v
		case "path":
			path = replacePath(path, p.Name, v)
		default:
			query[p.Name] = toStr(v)
		}
	}
	return c.Do(ctx, r.Method, path, query, body)
}
